"""Actual native memoization/collector controls with explicit non-SQL collaborators."""
from pathlib import Path
import json,re,subprocess,unittest
ROOT=Path(__file__).resolve().parents[2]
class SpaceCachePrime(unittest.TestCase):
 def test_actual_native_memoization_transition_prime_stability_and_source_mutation_refusal(self):
  p=subprocess.run(['php',str(ROOT/'support/governance/recovery/tests/space-prime-native-controls.php'),str(ROOT)],capture_output=True,text=True,timeout=10);self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');d=json.loads(p.stdout)
  for key in ('unprimed_real_DatabaseRef_refused','primed_repeat_and_late_Policy_master_ref_stable','real_new_viewer_cache_change_refused','stale_cached_description_refused','query_execution_and_policy_verdict_are_collaborators'):self.assertIs(d[key],True,key)
  self.assertEqual(d['native_query_executions'],1);self.assertEqual(d['native_policy_verdict_collaborator_calls'],4);self.assertFalse(d['transaction_active']);self.assertFalse(d['SQL_executed']);self.assertNotIn('PHID-',p.stdout)
 def test_database_ref_actual_route_and_policy_space_fixed_columns_support_observed_scope(self):
  lisk=(ROOT/'src/infrastructure/storage/lisk/PhabricatorLiskDAO.php').read_text();self.assertIn('PhabricatorDatabaseRef::getMasterDatabaseRefForApplication(',lisk)
  ref=(ROOT/'src/infrastructure/cluster/PhabricatorDatabaseRef.php').read_text()
  for start,stop,required in [('public static function getMasterDatabaseRefForApplication','public static function newIndividualRef','self::getMasterDatabaseRefs()'),('public static function getMasterDatabaseRefs','public function isApplicationHost','self::getAllMasterDatabaseRefs()'),('public static function getAllMasterDatabaseRefs','public static function getMasterDatabaseRefs','self::getClusterRefs()'),('public static function getClusterRefs','public static function newRefs','PhabricatorCaches::getRequestCache()')]:
   self.assertIn(required,ref[ref.index(start):ref.index(stop)])
  policy=(ROOT/'src/infrastructure/governance/recovery/PhorgeRecoveryRestorePolicySource.php').read_text();cols=re.search(r"array\(\$prefix.'_spaces','spaces_namespace',array\((.*?)\)\)",policy,re.S).group(1);policy_columns=set(re.findall(r"'([a-zA-Z]+)'",cols))
  p=subprocess.run(['php','-r',"require$argv[1].'/support/runtime/src/object/Phobject.php';require$argv[1].'/src/infrastructure/governance/recovery/PhorgeRecoverySpacesSourceFacts.php';echo json_encode((new ReflectionMethod(PhorgeRecoverySpacesSourceFacts::class,'columns'))->invoke(null));",str(ROOT)],capture_output=True,text=True,timeout=10);self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(set(json.loads(p.stdout)),policy_columns)
 def test_real_native_priming_precedes_ticket_and_no_bound_cache_clear_is_introduced(self):
  source=(ROOT/'support/governance/recovery/restore-review-cases.php').read_text();call='governance_recovery_restore_prime_space_cache($fixture,$conn,array($actor,$reviewer,$ordinary))';self.assertLess(source.index(call),source.index("$input=array('native_stop_transaction'"))
  self.assertLess(source.index("'requestCache'))->setValue(null,null)"),source.index(call));self.assertEqual(source.count("'requestCache'))->setValue(null,null)"),1)
  helper=source[source.index('function governance_recovery_restore_prime_space_cache'):source.index('/** Unrun native integration draft.')]
  for item in ('PhabricatorSpacesNamespaceQuery::getAllSpaces()','PhabricatorSpacesNamespaceQuery::getDefaultSpace()','PhabricatorSpacesNamespaceQuery::getViewerSpaces($viewer)','PhorgeRecoverySpacesSourceFacts::capture($conn)->finish()','PhabricatorDatabaseRef::getLiveIndividualRef()','hash_equals($before,$after)'):self.assertIn(item,helper)
  self.assertNotIn('ReflectionProperty',helper);self.assertNotIn('setKey(',helper);self.assertNotIn('destroySpacesCache',helper)
 def test_actual_repeated_preview_assertion_rejects_second_source_drift(self):
  code=r'''class PhorgeRecoveryRestoreService{static function preview(...$args){$GLOBALS['calls']++;$v=['category'=>'technical-pause','expires_at'=>1,'families'=>[],'incomplete_families'=>array_fill(0,13,'uncovered'),'permit_state'=>'blocked','preview_is_authorization'=>false,'request_id'=>'synthetic','restoration_authorized'=>false,'review_state'=>'submitted-blocked','source_digest'=>str_repeat('a',64),'source_schema_version'=>6,'version'=>'1'];if($GLOBALS['bad']&&$GLOBALS['calls']===2)$v['source_digest']=str_repeat('b',64);return$v;}}$s=file_get_contents($argv[1].'/support/governance/recovery/restore-review-cases.php');$start=strpos($s,'    $before=$fingerprint();$preview=');$end=strpos($s,"    require_once __DIR__.'/partial-composition-cases.php';",$start);$body=substr($s,$start,$end-$start);$out=[];foreach([false,true]as$bad){$GLOBALS['bad']=$bad;$GLOBALS['calls']=0;$accepted=null;$check=static function($ok,$name)use(&$accepted){$accepted=$ok;};$fingerprint=static fn()=>'fixed';$approver=['context'=>new stdClass()];$id='synthetic';eval($body);$out[]=['accepted'=>$accepted,'calls'=>$GLOBALS['calls']];}echo json_encode($out);'''
  p=subprocess.run(['php','-r',code,str(ROOT)],capture_output=True,text=True,timeout=10);self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');self.assertEqual(json.loads(p.stdout),[{'accepted':True,'calls':2},{'accepted':False,'calls':2}])
